'use strict';
let counter = 0;
async function charge({ amount_cents, currency }) {
  counter += 1;
  return { charge_id: `ch_${counter}_${Date.now()}`, amount_cents, currency, status: 'succeeded' };
}
module.exports = { charge, _reset: () => { counter = 0; } };

'use strict';
const express = require('express');
const processor = require('./processor');

function makeApp() {
  const app = express();
  app.use(express.json());

  // TODO: add idempotency-key handling.
  app.post('/api/payments', async (req, res) => {
    const { amount_cents, currency } = req.body || {};
    if (!Number.isInteger(amount_cents) || amount_cents <= 0) {
      return res.status(400).json({ error: 'invalid_amount' });
    }
    const result = await processor.charge({ amount_cents, currency });
    res.status(201).json(result);
  });

  return app;
}

module.exports = { makeApp };

const request = require('supertest');
const { makeApp } = require('../src/server');
const processor = require('../src/processor');

beforeEach(() => processor._reset());

test('baseline: charges create unique ids', async () => {
  const app = makeApp();
  const a = await request(app).post('/api/payments').send({ amount_cents: 100, currency: 'INR' });
  const b = await request(app).post('/api/payments').send({ amount_cents: 100, currency: 'INR' });
  expect(a.body.charge_id).not.toBe(b.body.charge_id);
});

'use strict';
const express = require('express');
const processor = require('./processor');

const TTL_MS = 24 * 60 * 60 * 1000;
const cache = new Map(); // key -> { bodyHash, response, status, expiresAt }

function hashBody(b) { return JSON.stringify(b || {}); }

function sweep() {
  const now = Date.now();
  for (const [k, v] of cache) if (v.expiresAt < now) cache.delete(k);
}

function makeApp() {
  const app = express();
  app.use(express.json());

  app.post('/api/payments', async (req, res) => {
    const { amount_cents, currency } = req.body || {};
    if (!Number.isInteger(amount_cents) || amount_cents <= 0) {
      return res.status(400).json({ error: 'invalid_amount' });
    }
    const key = req.get('Idempotency-Key');
    if (key) {
      sweep();
      const cached = cache.get(key);
      const bodyHash = hashBody(req.body);
      if (cached) {
        if (cached.bodyHash !== bodyHash) {
          return res.status(422).json({ error: 'idempotency_key_mismatch' });
        }
        return res.status(cached.status).json(cached.response);
      }
      const result = await processor.charge({ amount_cents, currency });
      cache.set(key, { bodyHash, response: result, status: 201, expiresAt: Date.now() + TTL_MS });
      return res.status(201).json(result);
    }
    const result = await processor.charge({ amount_cents, currency });
    res.status(201).json(result);
  });

  return app;
}

module.exports = { makeApp };

