npm install --silent --no-audit --no-fund && cat > tests/hidden.test.js <<'EOF'
const request = require('supertest');
const { makeApp } = require('../src/server');
const processor = require('../src/processor');

beforeEach(() => processor._reset());

test('same key + same body returns cached response', async () => {
  const app = makeApp();
  const a = await request(app).post('/api/payments').set('Idempotency-Key', 'k1').send({ amount_cents: 200, currency: 'INR' });
  const b = await request(app).post('/api/payments').set('Idempotency-Key', 'k1').send({ amount_cents: 200, currency: 'INR' });
  expect(a.body.charge_id).toBe(b.body.charge_id);
});

test('same key + different body returns 422', async () => {
  const app = makeApp();
  await request(app).post('/api/payments').set('Idempotency-Key', 'k2').send({ amount_cents: 200, currency: 'INR' });
  const r = await request(app).post('/api/payments').set('Idempotency-Key', 'k2').send({ amount_cents: 999, currency: 'INR' });
  expect(r.status).toBe(422);
  expect(r.body.error).toBe('idempotency_key_mismatch');
});

test('missing key still works', async () => {
  const app = makeApp();
  const r = await request(app).post('/api/payments').send({ amount_cents: 100, currency: 'INR' });
  expect(r.status).toBe(201);
});
EOF
